import '../domain/request_repository.dart';import '../domain/entities/request_entity.dart';import 'request_datasource.dart';class RequestRepositoryImpl implements RequestRepository{RequestRepositoryImpl(this.source);final RequestDatasource source;Future<RequestEntity>create(Map<String,dynamic>d)=>source.create(d).then(RequestEntity.fromJson);Future<List<RequestEntity>>mine()=>source.mine().then((x)=>x.map((e)=>RequestEntity.fromJson(e)).toList());Future<RequestEntity>detail(String id)=>source.detail(id).then(RequestEntity.fromJson);}
